"""Generate the handoff report from measured artifacts, never fabricated metrics."""
import json

from ml.pipeline import ROOT


def main():
    quality = json.loads((ROOT / "reports/quality-report.json").read_text(encoding="utf-8"))
    report = json.loads((ROOT / "reports/backtest.json").read_text(encoding="utf-8"))
    registry = json.loads((ROOT / "ml/models/registry.json").read_text())
    def f(value):
        return f"{value:,.0f}"
    lines = ["# หลักฐานการพัฒนา — 25 ตุลาคม 2026", "", "สร้างโปรเจกต์ใหม่ที่ D:/Football Prediction AI โดยไม่แก้โค้ดหรือเชื่อมฐานข้อมูลของ D:/Live score Project", "", "## งานที่ทำสำเร็จจริง", "", "- Historical importer pin source commit, ตรวจ working tree, score normalizer สองรูปแบบ, explicit aliases, league mapping, dedup/conflict handling, status/date/time validation, quarantine และ accepted dataset", "- League prior, Elo/home advantage/cold start, Poisson/shrinkage/scoreline probabilities และ feature replay แบบวันเดียวกันไม่ใช้ผลข้ามกัน", "- Logistic Regression จริงผ่าน NumPy/SciPy และ XGBoost native CPU, expanding walk-forward validation สอง fold, final holdout ที่ไม่ใช้เลือกโมเดล", "- JSON Model Registry พร้อม code/runtime/dataset/config provenance, checksums, immutable versions, local packaging และ manual promotion/rollback", "- React ภาษาไทยพร้อม league filter, match details, probability/scorelines, quality และ performance จริง", "- Worker/D1 local migrations, mock API client, quota/cache, signed internal endpoints, idempotent jobs, immutable prediction/feature snapshots และ result evaluation", "- CI/training/offline-batch/manual-release workflows เตรียมแล้ว; ยังไม่ได้ push หรือรันบน GitHub", "", "## ข้อมูลที่รับและกัก", "", f"อ่าน {f(quality['total_source_rows'])} แถว: รับ {f(quality['accepted'])}, กัก {f(quality['quarantined'])}, ไม่นำเข้าใน scope {f(quality['excluded'])}", "", "Accepted หมายถึงรับสำหรับทดลองแบบใช้ประวัติก่อนวันแข่ง ยังติด unverified สำหรับ source dates/timezones และ cross-provider identity ไม่ใช่ยืนยันว่าข้อมูลทุกนัดถูกต้องจากผู้จัดการแข่งขัน", "", "| ลีก | รับสำหรับฝึก |", "|---|---:|"]
    for league in ["en.1", "es.1", "de.1"]:
        lines.append(f"| {league} | {f(sum(s['accepted'] for s in quality['per_league_season'] if s['league']==league))} |")
    lines += ["", "| ฤดูกาล | EPL | La Liga | Bundesliga |", "|---|---:|---:|---:|"]
    seasons = sorted({s["season"] for s in quality["per_league_season"] if s["league"] in {"en.1", "es.1", "de.1"}})
    for season in seasons:
        cells = []
        for league in ["en.1", "es.1", "de.1"]:
            entry = next((s for s in quality["per_league_season"] if s["season"] == season and s["league"] == league), None)
            cells.append(f(entry["accepted"]) if entry else "ไม่มีไฟล์")
        lines.append("| " + season + " | " + " | ".join(cells) + " |")
    lines += ["", "| เหตุผลที่กัก (ทั้ง repository) | จำนวน |", "|---|---:|"]
    lines.extend(f"| {reason} | {f(n)} |" for reason, n in quality["quarantine_reasons"].items())
    lines += ["", "66 นัดที่ผิดลำดับยังไม่ถูกแก้วันที่ อีก 314 นัดของฤดูกาลเดียวกันพักไว้ด้วย รวม EPL 2019/20 ทั้ง 380 นัด ไม่มีการเติม missing score เป็น 0–0 ข้อมูลนอก 3 ลีกที่มีผลใช้ได้ 73,214 แถวและ full enrichment 881 แถวถูกแยกเป็น excluded; ไม่ควรนับ excluded ทั้งหมดเป็นข้อมูลเสีย", "", "## ผลโมเดลที่รันจริง", "", "Validation: 2022/23 และ 2023/24, final holdout: 2024-07-01 ถึงก่อน 2025-07-01 รวม 1,055 นัด เกณฑ์ถูกกำหนดไว้ใน policy.json ก่อนรันประเมิน", "", "| โมเดล | Log Loss ↓ | Brier ↓ | Accuracy | ECE ↓ |", "|---|---:|---:|---:|---:|"]
    for name, groups in report["final_holdout"]["metrics"].items():
        m = groups["all"]
        lines.append(f"| {name} | {m['log_loss']:.4f} | {m['brier']:.4f} | {m['accuracy']*100:.2f}% | {m['ece']:.4f} |")
    selected = report["selection"]["selected_before_holdout"]
    m = report["final_holdout"]["metrics"][selected]["all"]
    ci = m["ci95_date_cluster_bootstrap"]["accuracy"]
    lines += ["", f"เลือก **{selected}** จาก validation; baseline ที่ดีที่สุดบน validation คือ {report['selection']['baseline']} Challenger ผ่านเกณฑ์ทั้งสามลีกและทั้งสอง fold ก่อนดู holdout ผล holdout มี Log Loss ต่ำสุดในตัวเลขที่วัด แต่ไม่ได้กล่าวว่าชนะทุกโมเดลอย่างมีนัยสำคัญใน holdout", "", f"Accuracy 95% CI แบบ date-cluster bootstrap: {ci[0]*100:.2f}%–{ci[1]*100:.2f}% (500 รอบ) ความสัมพันธ์ระหว่างทีม/ฤดูกาลและปัญหาข้อมูลยังอาจทำให้ช่วงนี้มองโลกดีเกินจริง", "", "| ลีก · โมเดลที่เลือก | n | Log Loss | Brier | Accuracy |", "|---|---:|---:|---:|---:|"]
    for league in ["en.1", "es.1", "de.1"]:
        m = report["final_holdout"]["metrics"][selected][league]
        lines.append(f"| {league} | {m['n']} | {m['log_loss']:.4f} | {m['brier']:.4f} | {m['accuracy']*100:.2f}% |")
    lines += ["", "La Liga holdout มีผลขาด 10 นัด และ Bundesliga มี awarded ที่ไม่นำเข้า 1 นัด ทั้งห้าโมเดลประเมินบนตัวอย่างเดียวกัน การเลือกชุดข้อมูลอาจทำให้ผลมี bias", "", "## Registry และ reproducibility", "", f"- Candidate ล่าสุด: `{report['artifact_version']}`", f"- Dataset SHA-256: `{report['dataset_version']}`", f"- Source commit: `{report['source_commit']}`", f"- Frozen policy SHA-256: `{report['policy_sha256']}`", f"- Active model: `{registry['active']}`; MODEL_AUTO_PROMOTE=false", "- ตรวจ checksum และ training code provenance ผ่าน; เก็บ ZIP พร้อม SHA-256 ใน reports แล้ว ยังไม่อัปโหลด", "- Importer รันซ้ำให้ dataset hash เดิม; challenger training ซ้ำใน tests ให้ probabilities เหมือนเดิม; evaluation ที่รันซ้ำระหว่างตรวจ artifact metadata ให้ metrics เท่าเดิม โดยไม่เปลี่ยนเกณฑ์หรือ hyperparameters", "- Deployment artifact refit ถึงก่อน 2026-07-01; metrics มาจาก estimator ตามแต่ละ fold ไม่ใช่นำ deployment refit มาวัดบนข้อมูลที่เคยฝึก", "", "## ผลตรวจที่รันจริง", "", "| คำสั่ง | ผล |", "|---|---|", "| python -m pytest -q | 23 passed; หลังปรับ rollback test รันซ้ำเฉพาะ registry อีก 2 passed |", "| python -m ruff check ml scripts | ผ่าน |", "| npm test | 13 passed รวม D1 concurrency/cache/auth/replay/locking/feature history |", "| npm run lint | ผ่าน |", "| npm run typecheck / npm run build | ผ่าน |", "| npm run worker:check | dry-run bundle ผ่าน ไม่มี deployment |", "| npm run db:migrate:local | migrations 0001 และ 0002 ผ่านบน local D1 |", "| npm run db:seed:local | ผ่าน, 3 mock fixtures และผล holdout จริง |", "| npm run test:ui | 1 passed, desktop/mobile/filters/details/performance/quality, ไม่มี browser runtime error |", "| npm audit --audit-level=moderate | 0 vulnerabilities |", "| python -m pip check | ผ่าน |", "| Client bundle credential identifier scan | ผ่าน ไม่พบตัวระบุ secret ฝั่ง server ใน JS client |", "| Offline batch / model checksum / local ZIP packaging | ผ่าน |", "", "ภาพตรวจอยู่ใน reports/dashboard-desktop.png, dashboard-mobile.png, performance-desktop.png, calibration.png", "", "Application Control บล็อก DLL ของ scikit-learn จึงใช้ NumPy/SciPy และ XGBoost native API ที่โหลดได้ โดยไม่เปลี่ยนนโยบายความปลอดภัย Wrangler รุ่นแรกเริ่ม local runtime ไม่ได้; pin คู่ stable ที่ทดสอบแล้วแทน ดู ADR", "", "## ส่วนที่ยังไม่สำเร็จและยังไม่เปิดใช้งาน", "", "- API-Football จริง: **0 requests**; ยังไม่ตรวจบัญชี season permission, coverage, reset headers, minute limit, pagination และ Terms จริง", "- Cloudflare/GitHub cloud: ยังไม่สร้าง resources, secrets, production DB หรือ deployment; CI/workflows ยังไม่ได้รันบน GitHub", "- Live provider identity mapping และ live feature rebuilding ยังต้องตรวจ/ต่อผ่านข้อมูลจริง; ตอนนี้ feature builder/batch ใช้ข้อมูล historical ที่ยืนยัน provenance ได้และ mock fixtures", "- Current fixture schedule เป็น mock, historical features เก่า; ห้ามใช้สาธิตนี้อ้างเป็นคำทำนายเกมจริงปัจจุบัน", "- Public UI เป็น initial dashboard ยังไม่ใช่ระบบ admin ครบทุกหน้า, exact T-24h/T-6h/T-1h scheduling หรือ live-score service", "- Live sync เริ่มแค่หนึ่งลีก/หนึ่ง page; paging continuation, automatic season rollover, result-correction evaluation revisions, admin rate limits, nonce/ledger retention และ deployed CPU/free-tier measurement เป็นงานก่อนเปิดจริง", "- ไม่ตั้ง billing limits แทนผู้ใช้ และไม่รับประกันค่าใช้จ่ายจากโค้ดเพียงอย่างเดียว", "", "## ขั้นต่อไปสำหรับ integration", "", "1. ตรวจบัญชี API-Football direct/RapidAPI และ free-season availability โดยผู้ใช้ตั้ง key เป็น secret เอง", "2. ขออนุมัติ integration test หนึ่งลีกหนึ่งหน้า: คาด 1 billable fixtures request; status แยกตรวจว่า exempt จริงก่อนใช้", "3. ตรวจข้อมูล provider/team crosswalk, dates/status/pagination/headers แล้วต่อ current feature updates พร้อม parity tests", "4. ตั้ง Cloudflare Free/D1/secrets/limits และ GitHub private repo/workflow permissions ด้วยการอนุมัติแยก; เริ่ม preview mock ก่อน", "5. วัด Worker CPU, DB writes/reads/storage, failure recovery, rollback และ fresh predictions ก่อน production/scheduler", "", "ไฟล์ที่สร้างทั้งหมดดู reports/created-files.json; รายละเอียดจำนวนทุกลีก/ฤดูกาลดู reports/quality-by-season.csv; คำสั่งรันและ architecture อยู่ README.md, docs/ADR-0001.md และ docs/OPERATIONS.md", ""]
    research_path = ROOT / "reports/selection-v1/new-test.json"
    if research_path.exists():
        research = json.loads(research_path.read_text(encoding="utf-8"))
        measured = research["selected_result"]
        lines += ["", "## เพิ่มเติม — การคัดกรองอย่างละเอียด", "", "สร้างตัวทดลอง selective-research-v1 แยกจาก frozen baseline และ Model Registry เลือกจาก 12 กติกาบน validation ก่อนทดสอบ 2025/26 โดย estimator ฝึกจากข้อมูลก่อนช่วง test นี้เท่านั้น", "", f"กติกาที่เลือก: {research['chosen_rule']['id']}; เลือก {measured['n']}/{research['n_all']} คู่ ถูก {measured['correct']} คู่ ({measured['accuracy']*100:.2f}%) แต่ confirmation_passed=false เพราะจำนวนตัวอย่างรวมและ EPL ไม่ถึงเกณฑ์", "", "เพิ่มหน้าเว็บ “การคัดกรอง”, read-only /api/filtering และ /api/filtering/matches, migration 0003 และ seed หลักฐานรายคู่ 1,066 แถวแบบ immutable พร้อม pagination, league/status filters, เหตุผล/คำเตือนและ probability ก่อน-หลัง calibration", "", "ผลตรวจล่าสุด: Python 29 passed, TypeScript/D1 17 passed, UI desktop/mobile 2 passed, lint/typecheck/build และ Worker dry-run ผ่าน; migrations/seed ทั้งหมดเป็น local เท่านั้น", "", "ดู docs/DETAILED_FILTERING_TH.md และ reports/selection-v1/ สำหรับผล รายงานและภาพหน้าจอ ยังไม่เรียก API-Football จริง ไม่ deploy และไม่ promote โมเดล", ""]
    (ROOT / "docs/ACCEPTANCE.md").write_text("\n".join(lines), encoding="utf-8")
    card = {"version": report["artifact_version"], "task": "pre-match 1X2 multiclass probability estimation", "selected_algorithm": selected, "release_status": "candidate/manual approval required", "training_data": report["dataset_version"], "source_commit": report["source_commit"], "evaluation_protocol_sha256": report["policy_sha256"], "metrics": report["final_holdout"]["metrics"][selected], "limitations": report["limitations"] + ["Venue history uses last games without explicit time decay; returning clubs may have stale histories", "Do not reuse this holdout to tune future model variants"], "intended_use": "Research and a transparent pre-match dashboard after separately verified fresh data integration; not guarantees or betting advice"}
    (ROOT / "docs/MODEL_CARD.json").write_text(json.dumps(card, indent=2, ensure_ascii=False), encoding="utf-8")
    print("Wrote measured acceptance report and Model Card.")


if __name__ == "__main__":
    main()
